import random
import string
from typing import List

# Generator for HTTP request path strings possibly including query and custom verbs.
# Target fuzzer uses: ExtractRequestParts(path, {"custom","verb"}, verb)
# It may also append "?a=1&b=2" and/or ":custom" itself, but we still provide
# interesting, valid paths that exercise normalization, empty/root, repeated slashes,
# dot segments, percent-encodings, and custom verb suffixes.

SAFE_SEG_CHARS = string.ascii_letters + string.digits + "-_~."
RESERVED = ":/?#[]@!$&'()*+,;="

CUSTOM_VERBS = ["custom", "verb", "action", "download", "upload"]

def _rand_percent_encoded(rng: random.Random) -> str:
    # Return a percent-encoded byte, with bias toward ASCII reserved and slash.
    choices = [ord('/') , ord(':'), ord('-'), ord('_'), ord('.'), ord(' '), ord('*'), 37, 0, 127]
    if rng.random() < 0.5:
        b = rng.choice(choices) & 0xFF
    else:
        b = rng.randrange(0, 256)
    return "%" + format(b, "02X")

def _rand_seg(rng: random.Random) -> str:
    t = rng.random()
    if t < 0.15:
        return ""  # empty segment when combined with extra slashes
    if t < 0.30:
        return "."
    if t < 0.45:
        return ".."
    if t < 0.60:
        # include some percent-encodings inside
        base = ''.join(rng.choice(SAFE_SEG_CHARS) for _ in range(rng.randint(0, 6)))
        encs = ''.join(_rand_percent_encoded(rng) for _ in range(rng.randint(1, 3)))
        # interleave
        if rng.random() < 0.5:
            return base + encs
        else:
            return encs + base
    if t < 0.80:
        # mix safe and reserved (reserved should be treated as literal in segments)
        chars = SAFE_SEG_CHARS + RESERVED.replace('/', '')
        return ''.join(rng.choice(chars) for _ in range(rng.randint(1, 10)))
    # common realistic segment
    words = [
        "v1", "users", "projects", "instances", "operations", "items",
        "_dot_", "-dash-", "~tilde", "files", "media", "photos"
    ]
    w = rng.choice(words)
    # maybe add hex id
    if rng.random() < 0.5:
        w += '-' + ''.join(rng.choice('0123456789abcdef') for _ in range(rng.randint(4,12)))
    return w

def _build_path(rng: random.Random) -> str:
    # Decide leading slash style
    leading = ''
    roll = rng.random()
    if roll < 0.7:
        leading = '/'
    elif roll < 0.8:
        leading = '//'  # collapse behavior
    else:
        leading = ''  # relative path

    # Decide number of segments
    n = rng.randint(0, 8)

    segs: List[str] = []
    for i in range(n):
        segs.append(_rand_seg(rng))
        # Occasionally insert empty to create multiple slashes when joined
        if rng.random() < 0.2:
            segs.append("")

    # Occasionally create trailing slash(s)
    trailing_slashes = ''
    if rng.random() < 0.3:
        trailing_slashes = '/' * rng.randint(1, 3)

    path = leading + '/'.join(segs) + trailing_slashes

    # Edge cases: ensure we sometimes produce root-only or empty
    if n == 0 and rng.random() < 0.5:
        path = '/' if leading else ''

    # Occasionally append a custom verb (the extractor only recognizes "custom" and "verb")
    if rng.random() < 0.4:
        verb = rng.choice(["custom", "verb"]) if rng.random() < 0.8 else rng.choice(CUSTOM_VERBS)
        path += ':' + verb

    # Optionally embed percent-encodings near boundaries
    if rng.random() < 0.35:
        insert_at = rng.randrange(0, len(path) + 1)
        path = path[:insert_at] + _rand_percent_encoded(rng) + path[insert_at:]

    # Optionally include a query string (even though fuzzer may add its own)
    if rng.random() < 0.5:
        qs_parts = []
        # include both system-like (to be ignored) and regular params
        keys = ["$alt", "$trace", "pretty", "a", "b", "uploadType", "q"]
        for _ in range(rng.randint(1, 4)):
            k = rng.choice(keys)
            v_choice = rng.random()
            if v_choice < 0.33:
                v = ''.join(rng.choice(SAFE_SEG_CHARS) for _ in range(rng.randint(0, 6)))
            elif v_choice < 0.66:
                v = _rand_percent_encoded(rng)
            else:
                v = ''
            qs_parts.append(f"{k}={v}")
        path += '?' + '&'.join(qs_parts)

    return path


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create a mixture of paths with varying complexity, pick one per call.
    # Ensure size <= 4096 bytes.
    # Bias to realistic but also include corner cases.
    choice = rng.random()
    if choice < 0.2:
        # Root or near-root cases
        options = ['/', '', '///', '/./', '/../', '/%2F', '/:custom']
        s = rng.choice(options)
    elif choice < 0.35:
        # Simple REST-like path
        s = '/' + '/'.join(filter(None, [
            'v1', 'projects', 'p-' + ''.join(rng.choice('0123456789abcdef') for _ in range(8)),
            'locations', rng.choice(['us', 'eu', 'asia']),
            rng.choice(['instances','buckets','datasets']),
            ''.join(rng.choice(SAFE_SEG_CHARS) for _ in range(rng.randint(3,10)))
        ]))
        if rng.random() < 0.5:
            s += ':' + rng.choice(["custom", "verb"])  # recognized
        if rng.random() < 0.5:
            s += '?a=1&b=two'
    else:
        s = _build_path(rng)

    # Trim to 4096 bytes
    if len(s) > 4096:
        s = s[:4096]

    return s.encode('utf-8', errors='ignore')
